import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_group_norm_hardtanh_kernel(
    const float* input,
    const float* gamma,
    const float* beta,
    float* output,
    int batch_size,
    int out_features,
    int num_groups,
    float hardtanh_min,
    float hardtanh_max
) {
    const int group_size = out_features / num_groups;
    const int batch_group_idx = blockIdx.x;
    const int batch_idx = batch_group_idx / num_groups;
    const int group_idx = batch_group_idx % num_groups;

    if (batch_idx >= batch_size) return;

    const int feature_start = group_idx * group_size;
    const int feature_end = feature_start + group_size;

    extern __shared__ float smem[];
    float* shared_sum = smem;
    float* shared_sqsum = &smem[blockDim.x];

    float thread_sum = 0.0f;
    float thread_sqsum = 0.0f;

    for (int f = threadIdx.x; f < group_size; f += blockDim.x) {
        const int feat_idx = feature_start + f;
        const float val = input[batch_idx * out_features + feat_idx];
        thread_sum += val;
        thread_sqsum += val * val;
    }

    shared_sum[threadIdx.x] = thread_sum;
    shared_sqsum[threadIdx.x] = thread_sqsum;
    __syncthreads();

    for (int stride = blockDim.x/2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + stride];
            shared_sqsum[threadIdx.x] += shared_sqsum[threadIdx.x + stride];
        }
        __syncthreads();
    }

    const float mean = shared_sum[0] / group_size;
    const float var = shared_sqsum[0] / group_size - mean * mean;
    const float inv_std = rsqrtf(var + 1e-5f);

    for (int f = threadIdx.x; f < group_size; f += blockDim.x) {
        const int feat_idx = feature_start + f;
        const float val = input[batch_idx * out_features + feat_idx];
        float out_val = (val - mean) * inv_std;
        out_val = out_val * gamma[feat_idx] + beta[feat_idx];
        out_val = fmaxf(hardtanh_min, fminf(out_val, hardtanh_max));
        output[batch_idx * out_features + feat_idx] = out_val;
    }
}

torch::Tensor fused_group_norm_hardtanh_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups,
    float hardtanh_min,
    float hardtanh_max
) {
    const int batch_size = input.size(0);
    const int out_features = input.size(1);
    const int group_size = out_features / num_groups;

    auto output = torch::empty_like(input);
    const int num_blocks = batch_size * num_groups;
    const int threads = 256;
    const size_t smem_size = 2 * threads * sizeof(float);

    fused_group_norm_hardtanh_kernel<<<num_blocks, threads, smem_size>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        out_features,
        num_groups,
        hardtanh_min,
        hardtanh_max
    );

    return output;
}
"""

cpp_wrapper = """
torch::Tensor fused_group_norm_hardtanh_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups,
    float hardtanh_min,
    float hardtanh_max
);
"""

fused_gn_ht = load_inline(
    name='fused_gn_ht',
    cpp_sources=cpp_wrapper,
    cuda_sources=fused_kernel_code,
    functions=['fused_group_norm_hardtanh_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, num_groups, hardtanh_min, hardtanh_max):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.num_groups = num_groups
        self.hardtanh_min = hardtanh_min
        self.hardtanh_max = hardtanh_max
        self.gamma = nn.Parameter(torch.ones(out_features))
        self.beta = nn.Parameter(torch.zeros(out_features))

    def forward(self, x):
        x = self.gemm(x)
        x = fused_gn_ht.fused_group_norm_hardtanh_cuda(
            x, 
            self.gamma, 
            self.beta,
            self.num_groups,
            self.hardtanh_min,
            self.hardtanh_max
        )
        return x
